"""Pydantic schemas for LLM provider messages, tools, requests, and responses."""

from enum import Enum
import json
import re
from typing import Any, Dict, List, Literal, Optional
from pydantic import BaseModel, Field, field_validator, model_validator

from app.providers.llm.exceptions import LLMResponseError


class MessageRole(str, Enum):
    """Allowed roles for conversation chat messages."""

    SYSTEM = "system"
    USER = "user"
    ASSISTANT = "assistant"
    TOOL = "tool"


class ToolCallFunction(BaseModel):
    """Function call metadata generated by an LLM."""

    name: str = Field(..., min_length=1, description="Name of the tool/function called")
    arguments: str = Field(
        ...,
        description="JSON string representation of arguments passed to the function",
    )


class ToolCall(BaseModel):
    """Represents a tool call requested by the model."""

    id: str = Field(..., min_length=1, description="Unique identifier for the tool call")
    type: Literal["function"] = Field(
        default="function",
        description="Type of tool invocation (currently 'function')",
    )
    function: ToolCallFunction

    def parse_arguments(self) -> Dict[str, Any]:
        """Safely deserializes the JSON arguments string into a Python dictionary.

        Returns:
            Dictionary containing the deserialized arguments.

        Raises:
            LLMResponseError: If the arguments string is not valid JSON or not an object.
        """
        raw = self.function.arguments.strip()
        if not raw:
            return {}
        try:
            parsed = json.loads(raw)
            if not isinstance(parsed, dict):
                raise ValueError("Arguments must deserialize to a JSON object (dict).")
            return parsed
        except (json.JSONDecodeError, ValueError) as exc:
            raise LLMResponseError(
                f"Malformed JSON arguments in tool call '{self.function.name}': {exc}"
            ) from exc


class ChatMessage(BaseModel):
    """Structured representation of a single conversation turn."""

    role: MessageRole = Field(..., description="Role of the message author")
    content: Optional[str] = Field(
        default=None,
        description="Text content of the message",
    )
    tool_calls: Optional[List[ToolCall]] = Field(
        default=None,
        description="Tool calls issued by an assistant message",
    )
    tool_call_id: Optional[str] = Field(
        default=None,
        description="ID of the tool call this message is responding to (role='tool')",
    )
    name: Optional[str] = Field(
        default=None,
        description="Optional author or function name",
    )

    @model_validator(mode="after")
    def validate_message_structure(self) -> "ChatMessage":
        """Enforces role-specific message content constraints."""
        if self.role == MessageRole.TOOL:
            if not self.tool_call_id or not self.tool_call_id.strip():
                raise ValueError("Tool messages must specify a non-empty 'tool_call_id'.")
            if self.content is None:
                raise ValueError("Tool messages must contain non-null 'content'.")
        elif self.role == MessageRole.ASSISTANT:
            has_content = self.content is not None and bool(self.content.strip())
            has_tools = bool(self.tool_calls)
            if not has_content and not has_tools:
                raise ValueError(
                    "Assistant message must contain either non-empty 'content' or at least one 'tool_call'."
                )
        else:
            # USER and SYSTEM roles
            if self.content is None or not self.content.strip():
                raise ValueError(
                    f"{self.role.value.capitalize()} messages must contain non-empty 'content'."
                )
        return self

    @classmethod
    def system(cls, content: str, name: Optional[str] = None) -> "ChatMessage":
        """Convenience constructor for system messages."""
        return cls(role=MessageRole.SYSTEM, content=content, name=name)

    @classmethod
    def user(cls, content: str, name: Optional[str] = None) -> "ChatMessage":
        """Convenience constructor for user messages."""
        return cls(role=MessageRole.USER, content=content, name=name)

    @classmethod
    def assistant(
        cls,
        content: Optional[str] = None,
        tool_calls: Optional[List[ToolCall]] = None,
        name: Optional[str] = None,
    ) -> "ChatMessage":
        """Convenience constructor for assistant messages."""
        return cls(role=MessageRole.ASSISTANT, content=content, tool_calls=tool_calls, name=name)

    @classmethod
    def tool_result(
        cls,
        tool_call_id: str,
        content: str,
        name: Optional[str] = None,
    ) -> "ChatMessage":
        """Convenience constructor for tool response messages."""
        return cls(
            role=MessageRole.TOOL,
            tool_call_id=tool_call_id,
            content=content,
            name=name,
        )


class ToolFunction(BaseModel):
    """Specification of an executable tool function."""

    name: str = Field(
        ...,
        min_length=1,
        max_length=64,
        description="Unique name of the tool function",
    )
    description: str = Field(
        ...,
        min_length=1,
        description="Detailed description of the tool's purpose and usage",
    )
    parameters: Dict[str, Any] = Field(
        default_factory=lambda: {"type": "object", "properties": {}},
        description="JSON Schema object describing the tool parameters",
    )

    @field_validator("name")
    @classmethod
    def validate_function_name(cls, v: str) -> str:
        cleaned = v.strip()
        if not re.match(r"^[a-zA-Z0-9_-]+$", cleaned):
            raise ValueError(
                "Tool name must contain only alphanumeric characters, underscores, and hyphens."
            )
        return cleaned


class ToolDefinition(BaseModel):
    """Provider-independent tool definition."""

    type: Literal["function"] = Field(
        default="function",
        description="Type of tool definition (currently 'function')",
    )
    function: ToolFunction

    @classmethod
    def from_function(
        cls,
        name: str,
        description: str,
        parameters: Optional[Dict[str, Any]] = None,
    ) -> "ToolDefinition":
        """Convenience constructor for function tool definitions."""
        return cls(
            type="function",
            function=ToolFunction(
                name=name,
                description=description,
                parameters=parameters or {"type": "object", "properties": {}},
            ),
        )


class TokenUsage(BaseModel):
    """Token consumption metadata for an inference generation."""

    prompt_tokens: int = Field(default=0, ge=0, description="Tokens in the prompt")
    completion_tokens: int = Field(default=0, ge=0, description="Tokens in the completion")
    total_tokens: int = Field(default=0, ge=0, description="Total tokens consumed")

    @model_validator(mode="after")
    def compute_total_tokens(self) -> "TokenUsage":
        """Automatically computes total_tokens if not explicitly provided."""
        if self.total_tokens == 0 and (self.prompt_tokens > 0 or self.completion_tokens > 0):
            self.total_tokens = self.prompt_tokens + self.completion_tokens
        return self


class LLMRequest(BaseModel):
    """Request payload containing inference options and conversation input."""

    messages: List[ChatMessage] = Field(
        ...,
        min_length=1,
        description="Ordered list of conversation messages",
    )
    tools: Optional[List[ToolDefinition]] = Field(
        default=None,
        description="Optional list of tools available to the model",
    )
    temperature: Optional[float] = Field(
        default=None,
        ge=0.0,
        le=2.0,
        description="Sampling temperature",
    )
    max_tokens: Optional[int] = Field(
        default=None,
        gt=0,
        description="Maximum tokens to generate",
    )
    model: Optional[str] = Field(
        default=None,
        description="Optional model identifier override",
    )


class LLMResponse(BaseModel):
    """Structured response returned by an LLM provider."""

    content: Optional[str] = Field(
        default=None,
        description="Text content generated by the model",
    )
    tool_calls: List[ToolCall] = Field(
        default_factory=list,
        description="Tool calls requested by the model",
    )
    finish_reason: Optional[str] = Field(
        default=None,
        description="Reason generation finished ('stop', 'tool_calls', 'length')",
    )
    usage: Optional[TokenUsage] = Field(
        default=None,
        description="Token usage statistics",
    )
    model: Optional[str] = Field(
        default=None,
        description="Model identifier that produced the completion",
    )
    provider: Optional[str] = Field(
        default=None,
        description="Name of the provider that handled the request",
    )

    @model_validator(mode="after")
    def validate_non_empty_response(self) -> "LLMResponse":
        """Ensures the response has either text content or at least one tool call."""
        has_content = self.content is not None and bool(self.content.strip())
        has_tools = len(self.tool_calls) > 0
        if not has_content and not has_tools:
            raise ValueError(
                "LLMResponse cannot have both empty content and empty tool_calls."
            )
        return self

    @property
    def has_tool_calls(self) -> bool:
        """Returns True if the response contains one or more tool calls."""
        return len(self.tool_calls) > 0

